import { useState, useEffect } from "react";

import axios from "axios";

import {
  useNavigate
} from "react-router-dom";

import "../css/homepage.css";

function Homepage() {

  const navigate =
    useNavigate();

  const [user, setUser] =
    useState(null);

  const [bookings, setBookings] =
    useState([]);

  const [showProfile, setShowProfile] =
    useState(false);

  useEffect(() => {

    const userData =
      localStorage.getItem(
        "user"
      );

    if (!userData) {

      navigate("/");

      return;

    }

    const parsedUser =
      JSON.parse(userData);

    setUser(parsedUser);

    axios
      .get(
        "http://localhost:5001/api/rooms"
      )

      .then((response) => {

        setBookings(
          response.data.rooms || []
        );

      })

      .catch((error) => {

        console.log(error);

      });

  }, [navigate]);

  // logout

  const logout = () => {
      {/* PROFILE POPUP */}
      {showProfile && (

        <div className="profile-overlay">

          <div className="profile-popup">

            <h2>
              PROFILE
            </h2>

            <hr />

            <p>
              <strong>
                ชื่อ:
              </strong>{" "}
              {user.displayname_th}
            </p>

            <p>
              <strong>
                เลขนักศึกษา:
              </strong>{" "}
              {user.username}
            </p>

            <p>
              <strong>
                คณะ:
              </strong>{" "}
              {user.faculty}
            </p>

            <p>
              <strong>
                สาขา:
              </strong>{" "}
              {user.department}
            </p>

            <p>
              <strong>
                Email:
              </strong>{" "}
              {user.email}
            </p>

            <div className="profile-buttons">

              <button
                className="close-btn"
                onClick={() =>
                  setShowProfile(false)
                }
              >
                ปิด
              </button>

              <button
                className="logout-btn"
                onClick={logout}
              >
                Logout
              </button>

            </div>

          </div>

        </div>

      )}
    localStorage.removeItem(
      "token"
    );

    localStorage.removeItem(
      "user"
    );

    navigate("/");

  };

  if (!user) {

    return <h1>Loading...</h1>;

  }

  return (

    <div className="homepage">

      {/* TOPBAR */}

      <nav className="topbar">

        <div className="nav-left">

          <div className="home-icon">

            Home

          </div>

        </div>

        <div className="nav-center">

          <span>
            MY BOOKING
          </span>

          <span>
            GUIDE
          </span>

          <span>
            RULE
          </span>

          <span>
            REVIEW
          </span>

        </div>

        <div className="nav-right">
          <button
            className="profile-btn"
            onClick={() =>
              setShowProfile(!showProfile)
            }
          >
            PROFILE 👤
          </button>
        </div>

      </nav>

      {/* HERO */}

      <div className="hero-section">

        <div className="hero-left">
          <img
            src="/logo.png"
            alt="logo"
            className="hero-logo"
          />
        </div>

        <div className="hero-line"></div>

        <div className="hero-right">

          <h1>
            BOOKING
            <br />
            ROOM
          </h1>
      </div>

      {/* CONTENT */}

      <div className="content-section">

        {/* FILTER */}

        <div className="filter-section">

          <div className="filter-group">

            <label>
              ชั้น
            </label>

            <select>

              <option>
                1
              </option>

              <option>
                2
              </option>

              <option>
                3
              </option>

            </select>

          </div>

          <div className="filter-group">

            <label>
              วันที่
            </label>
            <input
              type="date"
            />

          </div>
          </div>

          <div className="filter-group">

            <label>
              ค้นหาห้อง
            </label>

            <input
              type="text"
              placeholder="ค้นหาห้อง"
            />

          </div>

        </div>

        {/* ROOM LIST */}

